import React from "react";
import { BaseColumn, TableData } from "../Table/types";

/** Props every filter input receives, the filter counterpart of CellComponentProps. */
export interface FilterInputProps<V> {
  /** Unique DOM id for this input, generated by SearchFilters. */
  id: string;
  label: string;
  /** Undefined means the filter is not set. */
  value: V | undefined;
  onChange: (value: V | undefined) => void;
}

/**
 * Identifies which factory made a filter, so consumers can map its value to their own query format.
 * Adding a kind is a breaking change for every consumer that maps kinds.
 */
export type FilterKind = "options" | "range" | "boolean";

/**
 * A filter: the input to render plus how its value is read and written as a string.
 * Columns mix filters with different value types, so values are unknown here and each factory checks them.
 */
export interface FilterDef {
  kind: FilterKind;
  FilterComponent: React.FC<FilterInputProps<unknown>>;
  /** Returns undefined for a value that is not valid for this filter. */
  encode: (value: unknown) => string | undefined;
  /** Returns undefined for a string that is not a valid value. */
  decode: (raw: string) => unknown;
}

/** A column that can be chosen in a filter row. */
export interface FilterColumn<R extends TableData> extends BaseColumn<R> {
  filter: FilterDef;
}

/** Filter values keyed by column id. An unset filter has no key. */
export type FilterValues = Record<string, unknown>;

export interface FilterOption {
  value: string;
  label: string;
}
